static int write_and_test ( struct pci_dev * dev , const int where , const u32 val ) { u32 read ; int count ; edac_dbg ( 0 , "setting pci %02x:%02x.%x reg=%02x value=%08x\n" , dev -> bus -> number , PCI_SLOT ( dev -> devfn ) , PCI_FUNC ( dev -> devfn ) , where , val ) ; for ( count = 0 ; count < 10 ; count ++ ) { if ( count ) { msleep ( 100 ) ; } pci_write_config_dword ( dev , where , val ) ; pci_read_config_dword ( dev , where , & read ) ; } i7core_printk ( KERN_ERR , "Error during set pci %02x:%02x.%x reg=%02x " "write=%08x. Read=%08x\n" , dev -> bus -> number , PCI_SLOT ( dev -> devfn ) , PCI_FUNC ( dev -> devfn ) , where , val , read ) ; return - EINVAL ; } 